from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    selected = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            key = ('id', event['id'])
        else:
            key = ('anonymous', position)

        revision = event.get('revision', 0)
        previous = selected.get(key)
        if previous is None or revision >= previous[0]:
            selected[key] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in sorted(selected.values(), key=lambda item: item[1]):
        if event.get('void', False):
            continue

        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances[key] = balances.get(key, 0) + amount(event, data['rounding'])

    return {'balances': balances}

def _round_ratio(numerator, denominator, mode):
    if mode == 'floor':
        return numerator // denominator
    if mode == 'half_up':
        return (2 * numerator + denominator) // (2 * denominator)
    raise ValueError(f'Unsupported rounding mode: {mode}')


def amount(event, mode):
    gross = event['price'] * event.get('quantity', 1)
    discount_bp = max(0, min(10000, event.get('discount_bp', 0)))
    net = _round_ratio(gross * (10000 - discount_bp), 10000, mode)

    tax_bp = event.get('tax_bp', 0)
    tax = _round_ratio(net * tax_bp, 10000, mode)
    total = net + tax

    if event.get('kind') == 'refund':
        return -total
    return total
